<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\Interview;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class NotificationCenterController extends Controller{public function index(Request $request):JsonResponse{$preferences=DB::table('notification_preferences')->where('user_id',$request->user()->id)->first();return response()->json(['data'=>['preferences'=>$preferences,'notifications'=>DB::table('in_app_notifications')->where('user_id',$request->user()->id)->latest()->limit(50)->get()]]);}public function preferences(Request $request):JsonResponse{$data=$request->validate(['email_enabled'=>['required','boolean'],'push_enabled'=>['required','boolean'],'whatsapp_enabled'=>['required','boolean']]);DB::table('notification_preferences')->updateOrInsert(['user_id'=>$request->user()->id],[...$data,'whatsapp_consented_at'=>$data['whatsapp_enabled']?now():null,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Preferencias actualizadas.']);}public function subscribe(Request $request):JsonResponse{$data=$request->validate(['endpoint'=>['required','url','max:1000'],'public_key'=>['nullable','string'],'auth_token'=>['nullable','string']]);DB::table('push_subscriptions')->updateOrInsert(['endpoint'=>$data['endpoint']],['user_id'=>$request->user()->id,'public_key'=>$data['public_key']??null,'auth_token'=>$data['auth_token']??null,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['message'=>'Dispositivo registrado.']);}public function read(Request $request,int $notification):JsonResponse{DB::table('in_app_notifications')->where('id',$notification)->where('user_id',$request->user()->id)->update(['read_at'=>now()]);return response()->json(['message'=>'Notificación leída.']);}public function calendar(Request $request,Interview $interview){$application=$interview->application;$user=$request->user();$allowed=$application->user_id===$user->id||($user->account_type==='company'&&$user->companies()->whereKey($application->job->company_id)->exists());abort_unless($allowed,404);$start=$interview->scheduled_at->utc();$end=$start->copy()->addMinutes($interview->duration_minutes);$escape=fn($v)=>str_replace(["\r","\n",',',';'],['','\\n','\\,','\\;'],(string)$v);$ics="BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//EmpleateRD//Entrevista//ES\r\nBEGIN:VEVENT\r\nUID:interview-{$interview->id}@empleaterd.com\r\nDTSTAMP:".now()->utc()->format('Ymd\THis\Z')."\r\nDTSTART:".$start->format('Ymd\THis\Z')."\r\nDTEND:".$end->format('Ymd\THis\Z')."\r\nSUMMARY:".$escape($interview->title)."\r\nDESCRIPTION:".$escape($interview->notes)."\r\nLOCATION:".$escape($interview->location_or_link)."\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";return response($ics,200,['Content-Type'=>'text/calendar; charset=utf-8','Content-Disposition'=>'attachment; filename=entrevista-empleaterd.ics']);}}
